const { randomUUID } = require('crypto');
const logger = require('../utils/logger');
const errorEventService = require('../services/errorEventService');

/**
 * Global error handler
 */
const errorHandler = (err, req, res, next) => {
  const errorId = randomUUID();

  logger.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    errorId,
    requestId: req.requestId || req.get?.('x-request-id') || null,
  });

  void errorEventService.captureBackendError({
    errorId,
    err,
    req,
    statusCode: err.statusCode || 500,
  }).catch(() => {});

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    const errors = Object.values(err.errors).map(e => e.message);
    return res.status(400).json({
      success: false,
      error: 'Validation error',
      details: errors,
      errorId,
    });
  }

  // JWT error
  if (err.name === 'JsonWebTokenError') {
    return res.status(401).json({
      success: false,
      error: 'Invalid token',
      errorId,
    });
  }

  // JWT expired
  if (err.name === 'TokenExpiredError') {
    return res.status(401).json({
      success: false,
      error: 'Token expired',
      errorId,
    });
  }

  // Duplicate key error (PostgreSQL)
  if (err.code === '23505') {
    return res.status(409).json({
      success: false,
      error: 'Resource already exists',
      errorId,
    });
  }

  // File too large
  if (err.code === 'LIMIT_FILE_SIZE') {
    return res.status(413).json({
      success: false,
      error: 'File too large',
      maxSize: process.env.MAX_UPLOAD_SIZE || '50MB',
      errorId,
    });
  }

  // Default error
  const statusCode = err.statusCode || 500;
  const isProduction = (process.env.NODE_ENV || '').toLowerCase() === 'production';
  const exposeMessage = statusCode < 500 || !isProduction;
  res.status(statusCode).json({
    success: false,
    error: exposeMessage ? (err.message || 'Internal server error') : 'Internal server error',
    ...(err.errorCode ? { errorCode: err.errorCode } : {}),
    ...(err.code && typeof err.code === 'string' && !err.errorCode ? { errorCode: err.code } : {}),
    errorId,
    ...(!isProduction && { stack: err.stack }),
  });
};

/**
 * 404 handler
 */
const notFound = (req, res, next) => {
  const error = new Error(`Not found - ${req.originalUrl}`);
  error.statusCode = 404;
  next(error);
};

/**
 * Async handler wrapper
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

module.exports = {
  errorHandler,
  notFound,
  asyncHandler,
};
